-- Seed 妈妈 (Mom) as a Café visitor. Generated by
-- .claude/skills/add-cafe-character/scripts/build-seed.mjs from content/characters/mama.json.
-- Idempotent: safe to run again. Once seeded, Shop Admin → Café Characters is the place to
-- edit the character; this file never overwrites those edits.
--
-- Dev:  npx supabase db query --linked -f supabase/manual/2026-11-27-seed-cafe-mama.sql
-- Prod: only when the owner asks, with .claude/skills/add-cafe-character/scripts/run-prod-sql.mjs

begin;

insert into shop_characters (
  character_key, name_i18n, intro_i18n, token_name_i18n, token_icon_path,
  sprite_paths, lines_i18n, visits_cafe, is_active, display_order, visit_frequency, visit_limit
) values (
  $seed$mama$seed$,
  $seed${"en":"Mom","zh":"妈妈"}$seed$::jsonb,
  $seed${"en":"Mom grades math homework every day. Earn an A+!","zh":"妈妈每天批改数学作业，来拿个A+吧！"}$seed$::jsonb,
  $seed${"en":"A+ homework","zh":"A+作业纸"}$seed$::jsonb,
  $seed$/characters/mama/mama_token.png$seed$,
  $seed${"waiting":"/characters/mama/mama_waiting.png","delighted":"/characters/mama/mama_delighted.png"}$seed$::jsonb,
  $seed${"order":[{"en":"Homework all done? Then a milk tea for me, please!","zh":"作业写完了吗？先给妈妈来杯奶茶！"},{"en":"Grading is tiring. I'd love some soup dumplings!","zh":"改作业好累呀，想吃小笼包！"},{"en":"Mom's done with work! What's good today?","zh":"妈妈下班啦，今天有什么好吃的？"}],"served":[{"en":"Delicious! Here's an A+ for you!","zh":"真好吃！给你一张A+作业纸！"},{"en":"You made this perfectly. Full marks!","zh":"这一份做得太棒了，满分！"},{"en":"Thank you, sweetie! Mom is so happy!","zh":"谢谢宝贝，妈妈好开心！"}],"dismissed":[{"en":"That's okay. I'll come back after grading.","zh":"没关系，妈妈改完作业再来。"},{"en":"Okay, see you tomorrow!","zh":"好的，那我们明天见！"}]}$seed$::jsonb,
  true,
  true,
  (select coalesce(max(display_order) + 1, 0) from shop_characters),
  $seed$daily$seed$,
  3
)
on conflict (character_key) do nothing;

-- Orders: only if the character has none yet, so admin edits are never overwritten.
do $do$
declare
  v_orders jsonb := $seed$[{"tokenPrice":1,"items":[{"recipe":"bubble_tea","quantity":1}]},{"tokenPrice":2,"items":[{"recipe":"bun","quantity":2,"specialIngredients":["pork-filling"]}]},{"tokenPrice":2,"items":[{"recipe":"zongzi","quantity":2,"specialIngredients":["pork-filling"]}]},{"tokenPrice":2,"items":[{"recipe":"bun","quantity":1,"specialIngredients":["pork-filling"]},{"recipe":"bubble_tea","quantity":1}]},{"tokenPrice":2,"items":[{"recipe":"tibetan-sweet-tea","quantity":1}]}]$seed$::jsonb;
  v_order jsonb;
  v_order_id uuid;
  v_bad text;
  v_index integer := 0;
begin
  select string_agg(distinct item ->> 'recipe', ', ') into v_bad
  from jsonb_array_elements(v_orders) o, jsonb_array_elements(o -> 'items') item
  where not exists (
    select 1 from shop_recipes r
    where r.slug = item ->> 'recipe' and r.is_active and r.cook_method is not null
  );
  if v_bad is not null then
    raise exception 'Recipes missing, inactive or not cookable: %', v_bad;
  end if;

  -- A pinned variant may only use the recipe's own special ingredients.
  select string_agg(distinct (item ->> 'recipe') || ' + ' || key, ', ') into v_bad
  from jsonb_array_elements(v_orders) o
  cross join lateral jsonb_array_elements(o -> 'items') item
  cross join lateral jsonb_array_elements_text(coalesce(item -> 'specialIngredients', '[]'::jsonb)) as k(key)
  join shop_recipes r on r.slug = item ->> 'recipe'
  where not exists (
    select 1 from jsonb_array_elements(coalesce(r.special_ingredient_slots, '[]'::jsonb)) slot
    where slot ->> 'ingredientKey' = key
  );
  if v_bad is not null then
    raise exception 'Special ingredients these recipes do not offer: %', v_bad;
  end if;

  if exists (select 1 from shop_character_orders where character_key = $seed$mama$seed$) then
    return;
  end if;

  for v_order in select * from jsonb_array_elements(v_orders) loop
    insert into shop_character_orders (character_key, token_price, display_order)
    values ($seed$mama$seed$, (v_order ->> 'tokenPrice')::integer, v_index)
    returning id into v_order_id;

    insert into shop_character_order_items (order_id, recipe_id, quantity, special_ingredient_keys)
    select v_order_id, r.id, (item ->> 'quantity')::integer, item -> 'specialIngredients'
    from jsonb_array_elements(v_order -> 'items') item
    join shop_recipes r on r.slug = item ->> 'recipe';

    v_index := v_index + 1;
  end loop;
end;
$do$;

-- Token content: skips any title the character already has.
insert into shop_character_token_contents (character_key, title, body, display_order)
select $seed$mama$seed$, c.title, c.body, c.ord
from (values
  ($seed$鸡兔同笼$seed$, $seed$笼子里有鸡和兔一共8只，数一数一共有22只脚。鸡和兔各有几只？$seed$, 0),
  ($seed$植树问题$seed$, $seed$一条小路长20米，从头到尾每隔5米种一棵树，两头都要种。一共要种几棵树？$seed$, 1),
  ($seed$锯木头$seed$, $seed$把一根木头锯成4段，每锯一次要3分钟。一共要锯几分钟？$seed$, 2),
  ($seed$妈妈的年龄$seed$, $seed$妈妈今年35岁，孩子今年8岁。几年后，妈妈的年龄正好是孩子的4倍？$seed$, 3),
  ($seed$爬楼梯$seed$, $seed$从1楼走到3楼要走36级台阶。照这样，从1楼走到6楼要走几级台阶？$seed$, 4),
  ($seed$握握手$seed$, $seed$4个小朋友见面，每两个人都要握一次手。一共握了几次手？$seed$, 5),
  ($seed$分糖果$seed$, $seed$两个盒子里一共有20颗糖，第一盒比第二盒多4颗。每盒各有几颗糖？$seed$, 6),
  ($seed$敲钟$seed$, $seed$大钟敲3下要用2秒。照这样，敲6下要用几秒？$seed$, 7)
) as c(title, body, ord)
where not exists (
  select 1 from shop_character_token_contents t where t.character_key = $seed$mama$seed$ and t.title = c.title
);

commit;
